'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pkg = require( './../package.json' ).name;
var drotmg = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'float64'
};


// MAIN //

bench( pkg, function benchmark( b ) {
	var out;
	var d1;
	var d2;
	var x1;
	var y1;
	var i;

	d1 = discreteUniform( 100, -5, 5, options );
	d2 = discreteUniform( 100, -5, 5, options );
	x1 = discreteUniform( 100, -5, 5, options );
	y1 = discreteUniform( 100, -5, 5, options );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = drotmg( d1[ i%d1.length ], d2[ i%d2.length ], x1[ i%x1.length ], y1[ i%y1.length ] );
		if ( isnan( out[ i%5 ] ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnan( out[ i%5 ] ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
